import{t as e}from"./utils-COoNfFoj.js";var t={slug:`adam-biddlecombe`,influencerName:`Adam Biddlecombe`,influencerHandle:`@AdamBiddlecombe`,influencerAvatarUrl:`${e}/adam-biddlecombe-avatar.jpeg`,heroDescription:`Alongside my day job, I run a real estate business in the UK. The challenge is that I don’t have much free time, and finding the right properties can be difficult when you’re busy. So I built a tool that identifies opportunities, surfaces them for me, and ensures I never miss the next great investment.`,assetTitle:`UK Property Radar`,screenshotUrl:`${e}/adam-biddlecombe.png`,remixUrl:`https://www.perplexity.ai/computer/a/uk-property-radar-2X6SdMQRQIyXqroSGwGjdQ`,promptTitle:`Try Adam's prompt`,promptText:`Build a UK real estate market intelligence web app that automatically ingests and updates weekly data on property price movements, transaction volumes, and rental yields segmented by region and postcode. Present the data through clean, interactive dashboards with advanced filtering capabilities. Include an “Opportunity Radar” engine that analyzes planning applications, infrastructure developments, and Ofsted ratings to identify emerging high-growth areas. Implement a deal alert system that detects and surfaces properties listed below their estimated market value within user-defined target postcodes. Integrate a tracker for Bank of England interest rate changes and mortgage product updates, converting complex financial changes into concise, plain-English impact summaries for investors and buyers. Generate an automated weekly digest highlighting the top three hotspot areas, supported by key metrics, trend analysis, and visual snapshots. Also include a polished, shareable monthly market report featuring commentary, charts, and market insights formatted for client distribution or LinkedIn publishing, with options for PDF/DOC export and customizable branding.`};export{t as default};
